#include <stdio.h>

// int arr[] 는 사실 int *arr 이다
void printArr(int arr[], int len) {
    for (int i = 0; i < len; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

int main() {
    int data[3] = {10, 20, 30};

    // 배열 이름 data는 첫 번째 주소(&data[0])와 같다
    printArr(data, 3);

    return 0;
}
